16: func startGreenhouseDaemon(t *testing.T, binary, home string, env []string) time.Time {
17: 	t.Helper()
18: 	command := exec.Command(binary, "daemon")
19: 	command.Env = env
20: 	if err := command.Start(); err != nil {
21: 		t.Fatalf("start Greenhouse daemon from %s: %v", binary, err)
22: 	}
23: 	t.Cleanup(func() {
24: 		stop := exec.Command(binary, "stop")
25: 		stop.Env = env
26: 		if output, err := stop.CombinedOutput(); err != nil {
27: 			t.Errorf("stop explicitly started Greenhouse daemon: %v: %s", err, output)
28: 		}
29: 		if err := command.Wait(); err != nil {
30: 			t.Errorf("wait for Greenhouse daemon: %v", err)
31: 		}
32: 	})
33: 	pidFile := filepath.Join(home, "pid")
34: 	deadline := time.Now().Add(10 * time.Second)
35: 	for time.Now().Before(deadline) {
36: 		contents, err := os.ReadFile(pidFile)
37: 		if err == nil {
38: 			var pid int
39: 			if json.Unmarshal(contents, &pid) == nil && pid > 1 {
40: 				executable, err := os.Readlink(filepath.Join("/proc", strconv.Itoa(pid), "exe"))
41: 				if err != nil {
42: 					t.Fatalf("read Greenhouse daemon executable for PID %d: %v", pid, err)
43: 				}
44: 				want, _ := filepath.EvalSymlinks(binary)
45: 				got, _ := filepath.EvalSymlinks(executable)
46: 				if got != want {
47: 					t.Fatalf("Greenhouse daemon PID %d runs %s, want %s", pid, got, want)
48: 				}
49: 				ps := exec.Command("ps", "-o", "lstart=", "-p", strconv.Itoa(pid))
50: 				ps.Env = append(os.Environ(), "LC_ALL=C")
51: 				started, err := ps.Output()
52: 				if err != nil {
53: 					t.Fatalf("read Greenhouse daemon start time: %v", err)
54: 				}
55: 				daemonStartedAt, err := time.ParseInLocation("Mon Jan _2 15:04:05 2006", strings.TrimSpace(string(started)), time.Local)
56: 				if err != nil {
57: 					t.Fatalf("parse Greenhouse daemon start time %q: %v", started, err)
58: 				}
59: 				version, err := exec.Command("go", "version", "-m", binary).Output()
60: 				if err != nil || !strings.Contains(string(version), "b2f5610e07da") {
61: 					t.Fatalf("Greenhouse binary does not identify merged timestamp commit: %v\n%s", err, version)
62: 				}
63: 				t.Logf("Greenhouse daemon PID %d executable=%s started=%s version=%s", pid, got, daemonStartedAt.Format(time.RFC3339), strings.TrimSpace(string(version)))
64: 				return daemonStartedAt
65: 			}
66: 		}
67: 		time.Sleep(10 * time.Millisecond)
68: 	}
69: 	t.Fatalf("Greenhouse daemon did not write PID file %s", pidFile)
70: 	return time.Time{}
71: }
