+case "$1 $2" in
+  "auth status") exit 0 ;;
+  "pr list") printf '[]\\n' ;;
+  *) exit 1 ;;
+esac
+`
+	if err := os.WriteFile(filepath.Join(f.root, "bin", "gh"), []byte(ghScript), 0o700); err != nil {
+		t.Fatal(err)
+	}
+
+	type pull struct {
