+	}
+	defer func() {
+		_ = os.Remove(filepath.Join(control, "hold-reviews"))
+		for index := range workers {
+			if workers[index].cmd != nil && workers[index].cmd.Process != nil && workers[index].cmd.ProcessState == nil {
