+			parts := strings.Split(r.URL.Path, "/")
+			_ = json.NewEncoder(w).Encode(map[string]any{"total_count": 1, "check_runs": []map[string]string{{"name": "fixture-ci", "status": "completed", "conclusion": "success", "head_sha": parts[len(parts)-2]}}})
