+		gitTest(t, greenhouseEnv, workers[index].dir, "commit", "-m", fmt.Sprintf("Worker %d change", index+1))
+		attached := greenhouseAXI(t, ghBin, workers[index].dir, greenhouseEnv, map[string]any{"version": 2, "op": "attach"})
