+		}
+		var inspected struct {
+			Run struct {
+				StartedAt string `json:"started_at"`
+				Pipeline  struct {
+					Stages []struct {
+						Name       string `json:"name"`
+						StartedAt  string `json:"started_at"`
+						FinishedAt string `json:"finished_at"`
