86: func greenhouseStageTimestamps(snapshot greenhouseWatchSnapshot, stage string) (int64, int64, int64) {
87: 	runStarted := greenhouseTimestampMillis(snapshot.Run.StartedAt)
88: 	stageStarted := greenhouseTimestampMillis(snapshot.Run.StageStartedAt)
89: 	var stageFinished int64
90: 	if snapshot.Run.Pipeline != nil {
91: 		for _, result := range snapshot.Run.Pipeline.Stages {
92: 			if result.Name == stage {
93: 				if stageStarted == 0 {
94: 					stageStarted = greenhouseTimestampMillis(result.StartedAt)
95: 				}
96: 				stageFinished = greenhouseTimestampMillis(result.FinishedAt)
97: 				break
98: 			}
99: 		}
100: 	}
101: 	return runStarted, stageStarted, stageFinished
102: }
