16: func TestGreenhouseWatchUsesGreenhouseTimestampsAndFallsBackWhenAbsent(t *testing.T) {
17: 	started := "2026-11-20T00:00:00Z"
18: 	stageStarted := "2026-11-20T00:02:00Z"
19: 	stageStartedAt := "2026-11-20T00:01:00Z"
20: 	stageFinished := "2026-11-20T00:03:00Z"
21: 	var snapshot greenhouseWatchSnapshot
22: 	if err := json.Unmarshal([]byte(`{"run":{"started_at":"`+started+`","stage_started_at":"`+stageStartedAt+`","pipeline":{"stages":[{"name":"review","started_at":"`+stageStarted+`","finished_at":"`+stageFinished+`"}]}}}`), &snapshot); err != nil {
23: 		t.Fatal(err)
24: 	}
25: 	runAt, stageAt, finishedAt := greenhouseStageTimestamps(snapshot, "review")
26: 	wantRun := greenhouseTimestampMillis(started)
27: 	wantStage := greenhouseTimestampMillis(stageStartedAt)
28: 	wantFinished := greenhouseTimestampMillis(stageFinished)
29: 	if runAt != wantRun || stageAt != wantStage || finishedAt != wantFinished {
30: 		t.Fatalf("parsed Greenhouse timestamps = %d/%d/%d, want %d/%d/%d", runAt, stageAt, finishedAt, wantRun, wantStage, wantFinished)
31: 	}
32: 	if greenhouseTimestampMillis("not-a-timestamp") != 0 {
33: 		t.Fatal("invalid timestamps should trigger observation-time fallback")
